fn solve(n: i8) -> Vec<i8> {
    // Number of complete 7-day weeks
    let weeks = n / 7;
    // Remaining days beyond the complete weeks
    let r = n % 7;
    // Base days off from the complete weeks
    let base_off = weeks * 2;
    // Minimum extra days off from the remainder:
    // If r ≤ 5, you can fit all working days, so 0 days off;
    // if r > 5, then the extra days beyond 5 must be days off.
    let extra_min = if r > 5 { r - 5 } else { 0 };
    // Maximum extra days off from the remainder:
    // You can't have more than 2 days off in any 7-day span,
    // and you can't have more off days than the length of the remainder.
    let extra_max = if r >= 2 { 2 } else { r };
    // Return [min, max]
    vec![base_off + extra_min, base_off + extra_max]
}

